1	import type { ExpiryExtractionResponse } from '@/contracts/api';
2	
3	// SPEC F4: Gemini returns date components and this module turns them into a date. Pure.
4	//
5	// A date with no printed year resolves to its next occurrence on or after today: a package stamped
6	// with today's date is far more likely to mean today than a year from now.
7	
8	export interface DateComponents {
9	  raw_text?: string | null;
10	  date_type: ExpiryExtractionResponse['dateType'];
11	  year?: number | null;
12	  month?: number | null;
13	  day?: number | null;
14	  year_was_printed: boolean;
15	  ambiguous_order: boolean;
16	  confidence: ExpiryExtractionResponse['confidence'];
17	}
18	
19	const MONTH_CODES: Record<string, number> = { JA: 1, FE: 2, MR: 3, AL: 4, MA: 5, JN: 6, JL: 7, AU: 8, SE: 9, OC: 10, NO: 11, DE: 12 };
20	
21	// SPEC's pattern, bounded so "MA 2026" can't read as May 20 and "NORTH 12" can't read as November.
22	const CFIA = /(?<!\d)(\d{2,4})?\s*(?<![A-Z])(JA|FE|MR|AL|MA|JN|JL|AU|SE|OC|NO|DE)(?![A-Z])\s*(\d{1,2})(?!\d)/gi;
23	// "BB/MA" is the bilingual "best before / meilleur avant" marker, not the month of May.
24	const BEST_BEFORE_MARKER = /\b(?:B\.?B\.?\s*\/\s*M\.?A\.?|M\.?A\.?\s*\/\s*B\.?B\.?)(?![A-Z])/gi;
25	
26	export interface CfiaMatch {
27	  year: number | null;
28	  month: number;
29	  day: number;
30	}
31	
32	const fullYear = (y: number) => (y < 100 ? 2000 + y : y);
33	
34	export function parseCfia(rawText: string): CfiaMatch[] {
35	  const out: CfiaMatch[] = [];
36	  for (const m of rawText.replace(BEST_BEFORE_MARKER, ' ').matchAll(CFIA)) {
37	    const day = Number(m[3]);
38	    if (day < 1 || day > 31) continue;
39	    out.push({ year: m[1] ? fullYear(Number(m[1])) : null, month: MONTH_CODES[m[2].toUpperCase()], day });
40	  }
41	  return out;
42	}
43	
44	export function regexCrossCheck(x: DateComponents): ExpiryExtractionResponse['regexCrossCheck'] {
45	  const matches = x.raw_text ? parseCfia(x.raw_text) : [];
46	  if (matches.length === 0) return 'no_match';
47	  const year = x.year_was_printed && x.year != null ? fullYear(x.year) : null;
48	  const agrees = matches.some((m) => {
49	    const sameOrder = m.month === x.month && m.day === x.day;
50	    const swapped = x.ambiguous_order && m.month === x.day && m.day === x.month;
51	    return (sameOrder || swapped) && (m.year === null || year === null || m.year === year);
52	  });
53	  return agrees ? 'agree' : 'disagree';
54	}
55	
56	/** Same cap as expiryRawText in the pantry schema, so a long read can't block saving. */
57	const RAW_TEXT_MAX = 200;
58	
59	const pad = (n: number) => String(n).padStart(2, '0');
60	
61	/** YYYY-MM-DD, or null if that calendar day doesn't exist. */
62	function toIso(year: number, month: number, day: number): string | null {
63	  const d = new Date(Date.UTC(year, month - 1, day));
64	  if (d.getUTCFullYear() !== year || d.getUTCMonth() !== month - 1 || d.getUTCDate() !== day) return null;
65	  return `${year}-${pad(month)}-${pad(day)}`;
66	}
67	
68	function nextOccurrence(month: number, day: number, today: string): string | null {
69	  const start = Number(today.slice(0, 4));
70	  for (let year = start; year <= start + 8; year++) {
71	    const iso = toIso(year, month, day);
72	    if (iso && iso >= today) return iso;
73	  }
74	  return null;
75	}
76	
77	function shiftYears(iso: string, years: number): string {
78	  return `${Number(iso.slice(0, 4)) + years}${iso.slice(4)}`;
79	}
80	
81	export function assembleDate(x: DateComponents, today: string): ExpiryExtractionResponse {
82	  const base = {
83	    rawText: x.raw_text?.trim().slice(0, RAW_TEXT_MAX) || null,
84	    dateType: x.date_type,
85	    regexCrossCheck: regexCrossCheck(x),
86	    confidence: x.confidence,
87	  };
88	  const none: ExpiryExtractionResponse = { ...base, suggestedDate: null, candidates: [], needsUserChoice: false, yearInferred: false };
89	  if (x.date_type === 'packaged_on' || x.month == null || x.day == null) return none;
90	
91	  const printedYear = x.year_was_printed && x.year != null ? fullYear(x.year) : null;
92	  const orders: Array<[number, number]> = [[x.month, x.day]];
93	  if (x.ambiguous_order && x.month !== x.day) orders.push([x.day, x.month]);
94	
95	  const earliest = shiftYears(today, -1);
96	  const latest = shiftYears(today, 5);
97	  const candidates = [
98	    ...new Set(
99	      orders
100	        .filter(([month]) => month >= 1 && month <= 12)
101	        .map(([month, day]) => (printedYear === null ? nextOccurrence(month, day, today) : toIso(printedYear, month, day)))
102	        .filter((iso): iso is string => iso !== null && iso >= earliest && iso <= latest),
103	    ),
104	  ];
105	  if (candidates.length === 0) return none;
106	
107	  return {
108	    ...base,
109	    suggestedDate: candidates[0],
110	    candidates,
111	    needsUserChoice: candidates.length > 1,
112	    yearInferred: printedYear === null,
113	  };
114	}
115

