1	import 'server-only';
2	import { GoogleGenAI, type Part } from '@google/genai';
3	import type { ZodType } from 'zod';
4	import { getEnv } from '../env';
5	
6	let client: GoogleGenAI | null = null;
7	
8	function getClient(): GoogleGenAI {
9	  // Vertex AI via Application Default Credentials (`gcloud auth application-default login` locally).
10	  if (!client) {
11	    const env = getEnv();
12	    client = new GoogleGenAI({ vertexai: true, project: env.GOOGLE_CLOUD_PROJECT, location: env.GOOGLE_CLOUD_LOCATION });
13	    console.info(`[gemini] vertex project=${env.GOOGLE_CLOUD_PROJECT} location=${env.GOOGLE_CLOUD_LOCATION}`);
14	  }
15	  return client;
16	}
17	
18	export interface GeminiImage {
19	  mimeType: 'image/jpeg' | 'image/png' | 'image/webp' | 'image/heic' | 'image/heif';
20	  base64: string;
21	}
22	
23	async function callWithTimeout<T>(fn: (signal: AbortSignal) => Promise<T>, timeoutMs: number): Promise<T> {
24	  const controller = new AbortController();
25	  const timer = setTimeout(() => controller.abort(), timeoutMs);
26	  try {
27	    return await fn(controller.signal);
28	  } finally {
29	    clearTimeout(timer);
30	  }
31	}
32	
33	function stripJsonFences(text: string): string {
34	  return text
35	    .trim()
36	    .replace(/^```(?:json)?\s*/i, '')
37	    .replace(/```\s*$/, '')
38	    .trim();
39	}
40	
41	function tryParseJson(text: string): unknown {
42	  try {
43	    return JSON.parse(text);
44	  } catch {
45	    return undefined;
46	  }
47	}
48	
49	/**
50	 * JSON-mode call, NO tools (§10.3.1). Validates with zod; strips ```json
51	 * fences; 1 retry if the response doesn't parse or doesn't match `zod` —
52	 * structured output guarantees schema-shaped JSON, not correct values
53	 * (https://ai.google.dev/gemini-api/docs/structured-output), so callers must
54	 * still sanity-check the data.
55	 */
56	export async function geminiJson<T>(opts: {
57	  system?: string;
58	  text: string; // put the text prompt BEFORE images (docs tip)
59	  images?: GeminiImage[];
60	  jsonSchema: object; // Gemini JSON-Schema subset (§10.3.6)
61	  zod: ZodType<T>;
62	  model?: string;
63	  timeoutMs?: number;
64	}): Promise<{ data: T; model: string }> {
65	  const env = getEnv();
66	  const model = opts.model ?? env.GEMINI_MODEL;
67	  const timeoutMs = opts.timeoutMs ?? 30_000;
68	
69	  const parts: Part[] = [{ text: opts.text }];
70	  for (const image of opts.images ?? []) {
71	    parts.push({ inlineData: { mimeType: image.mimeType, data: image.base64 } });
72	  }
73	
74	  const attempt = async () => {
75	    const response = await callWithTimeout(
76	      (signal) =>
77	        getClient().models.generateContent({
78	          model,
79	          contents: [{ role: 'user', parts }],
80	          config: {
81	            systemInstruction: opts.system,
82	            responseMimeType: 'application/json',
83	            responseSchema: opts.jsonSchema,
84	            abortSignal: signal,
85	          },
86	        }),
87	      timeoutMs,
88	    );
89	    const parsed = tryParseJson(stripJsonFences(response.text ?? ''));
90	    return opts.zod.safeParse(parsed);
91	  };
92	
93	  const first = await attempt();
94	  if (first.success) return { data: first.data, model };
95	
96	  const second = await attempt();
97	  if (second.success) return { data: second.data, model };
98	
99	  throw new Error(`geminiJson: response did not match schema after 1 retry: ${second.error.message}`);
100	}
101	
102	/**
103	 * Grounded search call, NO response schema (avoids the 2025–26
104	 * grounding+JSON bugs documented in §9 F6). Reads `groundingMetadata` off
105	 * the first candidate (§17 item 1, confirmed against @google/genai 3.0.0).
106	 */
107	export async function geminiGroundedSearch(opts: {
108	  prompt: string;
109	  model?: string;
110	  timeoutMs?: number;
111	}): Promise<{
112	  text: string;
113	  sources: Array<{ uri: string; title: string | null }>;
114	  webSearchQueries: string[];
115	  searchEntryPointHtml: string | null;
116	}> {
117	  const env = getEnv();
118	  const model = opts.model ?? env.GEMINI_SEARCH_MODEL;
119	  const timeoutMs = opts.timeoutMs ?? 45_000;
120	
121	  const response = await callWithTimeout(
122	    (signal) =>
123	      getClient().models.generateContent({
124	        model,
125	        contents: [{ role: 'user', parts: [{ text: opts.prompt }] }],
126	        config: { tools: [{ googleSearch: {} }], abortSignal: signal },
127	      }),
128	    timeoutMs,
129	  );
130	
131	  const grounding = response.candidates?.[0]?.groundingMetadata;
132	  const sources = (grounding?.groundingChunks ?? [])
133	    .map((chunk) => chunk.web)
134	    .filter((web): web is { uri: string; title?: string } => Boolean(web?.uri))
135	    .map((web) => ({ uri: web.uri as string, title: web.title ?? null }));
136	
137	  return {
138	    text: response.text ?? '',
139	    sources,
140	    webSearchQueries: grounding?.webSearchQueries ?? [],
141	    searchEntryPointHtml: grounding?.searchEntryPoint?.renderedContent ?? null,
142	  };
143	}
144

