1	import type { ApiError, CreatePantryItemRequest, ListPantryResponse, UpdateMeRequest, UpdatePantryItemRequest } from '@/contracts/api';
2	import type { PantryItem, UserProfile } from '@/contracts/domain';
3	
4	// Browser-side client for Workstream B routes. Throws ApiClientError with the server's message.
5	
6	export class ApiClientError extends Error {
7	  constructor(
8	    message: string,
9	    public status: number,
10	    public code: string | null,
11	    public details?: unknown,
12	  ) {
13	    super(message);
14	  }
15	}
16	
17	export async function api<T>(path: string, init?: RequestInit & { json?: unknown }): Promise<T> {
18	  const { json, ...rest } = init ?? {};
19	  const res = await fetch(path, {
20	    ...rest,
21	    headers: { ...(json !== undefined ? { 'Content-Type': 'application/json' } : {}), ...rest.headers },
22	    body: json !== undefined ? JSON.stringify(json) : rest.body,
23	  });
24	  const text = await res.text();
25	  let data: unknown = null;
26	  try {
27	    data = text ? JSON.parse(text) : null;
28	  } catch {
29	    if (res.ok) throw new ApiClientError('Unexpected response from the server', res.status, null);
30	  }
31	  if (!res.ok) {
32	    const err = (data as ApiError | null)?.error;
33	    throw new ApiClientError(err?.message ?? `Request failed (${res.status})`, res.status, err?.code ?? null, err?.details);
34	  }
35	  return data as T;
36	}
37	
38	export const pantryApi = {
39	  list: (opts: { sort?: 'expiry' | 'name'; includeEmpty?: boolean } = {}) =>
40	    api<ListPantryResponse>(
41	      `/api/pantry?sort=${opts.sort ?? 'expiry'}&includeEmpty=${opts.includeEmpty ? 'true' : 'false'}`,
42	    ),
43	  create: (body: CreatePantryItemRequest) => api<PantryItem>('/api/pantry', { method: 'POST', json: body }),
44	  update: (id: string, body: UpdatePantryItemRequest) =>
