2	
3	import dynamic from 'next/dynamic';
4	import { useRef, useState } from 'react';
5	import { useRouter } from 'next/navigation';
6	import type { LabelExtractionResponse } from '@/contracts/api';
7	import type { Product, ProductSource } from '@/contracts/domain';
8	import { Badge, Button, Card, useToast } from '@/components/ui';
9	import { pantryApi } from '@/features/pantry/api';
10	import { ProductForm, type ProductFormValues } from '@/features/pantry/ProductForm';
11	import { scanApi } from './api';
12	import type { ScannedCode } from './BarcodeScanner';
13	import { ExpiryCapture } from './ExpiryCapture';
14	import { PhotoCapture } from './PhotoCapture';
15	import { draftToFormInitial, productToFormInitial } from './pure';
16	
17	// SPEC UF2/UF3: scan → found card, or not found → label photo → confirm. The manual form is
18	// reachable from every step.
19	
20	const BarcodeScanner = dynamic(() => import('./BarcodeScanner').then((m) => m.BarcodeScanner), { ssr: false });
21	
22	type Step =
23	  | { kind: 'scan'; notice?: string; ignoreGtin?: string }
24	  | { kind: 'looking' }
25	  | { kind: 'found'; product: Product }
26	  | { kind: 'not_found'; gtin: string }
27	  | { kind: 'label'; gtin: string | null; message?: string }
28	  | { kind: 'draft'; response: LabelExtractionResponse }
29	  | { kind: 'manual'; gtin: string | null };
30	
31	function FoundCard({ product }: { product: Product }) {
32	  const kcal = product.per100.energyKcal;
33	  const per = product.basis === '100ml' ? '100 ml' : '100 g';
34	  const size = product.packageQuantity?.text ?? (product.packageQuantity ? `${product.packageQuantity.value} ${product.packageQuantity.unit}` : null);
35	  return (
36	    <Card className="flex gap-4">
37	      {product.imageUrl?.startsWith('https://') && (
38	        // eslint-disable-next-line @next/next/no-img-element -- third-party product photo, any host
39	        <img src={product.imageUrl} alt="" className="h-24 w-24 shrink-0 rounded-xl object-contain" />
40	      )}
41	      <div className="min-w-0">
42	        <h2 className="font-display text-xl font-semibold">{product.name}</h2>
43	        {product.brand && <p className="text-sm text-muted">{product.brand}</p>}
44	        <p className="mt-1 text-sm">
45	          {kcal != null ? `${Math.round(kcal)} kcal per ${per}` : 'No calorie data'}
46	          {size ? ` · ${size}` : ''}
47	        </p>
48	        <p className="mt-1 text-xs text-muted">Product data: Open Food Facts (ODbL)</p>
49	      </div>
50	    </Card>
51	  );
52	}
53	
54	export function AddProductFlow() {
55	  const router = useRouter();
56	  const toast = useToast();
57	  const [step, setStep] = useState<Step>({ kind: 'scan' });
58	  const [readingLabel, setReadingLabel] = useState(false);
59	  // Bumped whenever the user moves on, so a slow response can't replace what they're doing now.
60	  const latestRequest = useRef(0);
61	
62	  async function lookup(code: ScannedCode) {
63	    const request = ++latestRequest.current;
64	    setStep({ kind: 'looking' });
65	    try {
66	      // lookupCode, not gtin: it keeps an EAN-8 as 8 digits for the providers.
67	      const r = await scanApi.lookup(code.lookupCode);
68	      if (request !== latestRequest.current) return;
69	      if (r.status === 'found') setStep({ kind: 'found', product: r.product });
70	      else if (r.status === 'not_found') setStep({ kind: 'not_found', gtin: r.gtin });
71	      else setStep({ kind: 'scan', notice: "That barcode doesn't look valid", ignoreGtin: code.gtin });
72	    } catch (e) {
73	      if (request !== latestRequest.current) return;
74	      setStep({ kind: 'scan', notice: e instanceof Error ? e.message : 'Could not look up that barcode.', ignoreGtin: code.gtin });
75	    }
76	  }
77	
78	  async function readLabel(photos: Blob[], gtin: string | null) {
79	    const request = ++latestRequest.current;
80	    setReadingLabel(true);
81	    try {
82	      const response = await scanApi.readLabel(photos, gtin);
83	      if (request !== latestRequest.current) return;
84	      if (response.isFoodProduct) setStep({ kind: 'draft', response });
85	      else setStep({ kind: 'label', gtin, message: "That doesn't look like a food product. Try another photo, or enter it by hand." });
86	    } catch (e) {
87	      if (request !== latestRequest.current) return;
88	      setStep({ kind: 'label', gtin, message: e instanceof Error ? e.message : "We couldn't read that photo." });
89	    } finally {
90	      setReadingLabel(false);
91	    }
92	  }
93	
94	  async function save(values: ProductFormValues, gtin: string | null, source: ProductSource, userVerified: boolean) {
95	    await pantryApi.create({ ...values, gtin, source, userVerified });
96	    toast(`${values.name} added`);
97	    router.push('/pantry');
98	    router.refresh();
99	  }
100	
101	  const rescan = () => setStep({ kind: 'scan' });
102	  const expirySlot = (apply: Parameters<typeof ExpiryCapture>[0]['onConfirm']) => <ExpiryCapture onConfirm={apply} />;
103	
104	  return (
105	    <div className="grid gap-6">
106	      {step.kind === 'scan' && <BarcodeScanner onCode={(c) => void lookup(c)} notice={step.notice} ignoreGtin={step.ignoreGtin} />}
107	
108	      {step.kind === 'looking' && (
109	        <p role="status" className="text-sm text-muted">
110	          Looking up that barcode…
111	        </p>
112	      )}
113	
114	      {step.kind === 'found' && (
115	        <>
116	          <FoundCard product={step.product} />
117	          <ProductForm
118	            key={step.product.gtin}
119	            initial={productToFormInitial(step.product)}
120	            expirySlot={expirySlot}
121	            submitLabel="Add to pantry"
122	            onCancel={rescan}
123	            onSubmit={(v) => save(v, step.product.gtin, step.product.source, false)}
124	          />
125	        </>
126	      )}
127	
128	      {step.kind === 'not_found' && (
129	        <Card>
130	          <h2 className="font-display text-xl font-semibold">We couldn&apos;t find this product.</h2>
131	          <div className="mt-4 flex flex-wrap gap-3">
132	            <Button onClick={() => setStep({ kind: 'label', gtin: step.gtin })}>Take photo of label</Button>
133	            <Button variant="secondary" onClick={() => setStep({ kind: 'manual', gtin: step.gtin })}>
134	              Enter manually
135	            </Button>
136	            <Button variant="ghost" onClick={rescan}>
137	              Scan another
138	            </Button>
139	          </div>
140	        </Card>
141	      )}
142	
143	      {step.kind === 'label' && (
144	        <Card>
145	          <h2 className="font-display text-xl font-semibold">Photos of the product</h2>
146	          <p className="mb-4 mt-1 text-sm text-muted">Add the front and the nutrition table, up to 3 photos.</p>
147	          <PhotoCapture
148	            max={3}
149	            busy={readingLabel}
150	            addLabel="Take photo"
151	            submitLabel="Read label"
152	            onSubmit={(p) => void readLabel(p, step.gtin)}
153	          />
154	          {step.message && (
155	            <p role="alert" className="mt-4 rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
156	              {step.message}
157	            </p>
158	          )}
159	        </Card>
160	      )}
161	
162	      {step.kind === 'draft' &&
163	        (() => {
164	          const { initial, nutritionDropped } = draftToFormInitial(step.response.draft);
165	          return (
166	            <>
167	              {nutritionDropped && (
168	                <p className="rounded-xl bg-warn-soft px-3 py-2 text-sm">
169	                  The label&apos;s serving weight couldn&apos;t be read, so its nutrition values were left out.
170	                </p>
171	              )}
172	              <ProductForm
173	                initial={initial}
174	                flaggedFields={step.response.flaggedFields}
175	                badge={<Badge tone="ai">Read by AI, please confirm</Badge>}
176	                expirySlot={expirySlot}
177	                submitLabel="Confirm"
178	                onCancel={rescan}
179	                onSubmit={(v) => save(v, step.response.draft.gtin, 'gemini_photo', true)}
180	              />
181	            </>
182	          );
183	        })()}
184	
185	      {step.kind === 'manual' && (
186	        <ProductForm expirySlot={expirySlot} submitLabel="Add to pantry" onCancel={rescan} onSubmit={(v) => save(v, step.gtin, 'manual', true)} />
187	      )}
188	
189	      {step.kind !== 'manual' && step.kind !== 'draft' && step.kind !== 'not_found' && (
190	        <div>
191	          <Button
192	            variant="ghost"
193	            onClick={() => {
194	              latestRequest.current++;
195	              setStep({ kind: 'manual', gtin: step.kind === 'found' ? step.product.gtin : null });
196	            }}
197	          >
198	            Enter manually
199	          </Button>
200	        </div>
201	      )}
202	    </div>
203	  );
204	}
